import{_ as t,o as e,c as a,ac as r}from"./chunks/framework.B-3EzaJq.js";const b=JSON.parse('{"title":"三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信","description":"","frontmatter":{"prev":{"text":"三十七位老同志请求不再担任中国共产党中央顾问委员会委员致党的十二届四中全会的信","link":"./三十七位老同志请求不再担任中国共产党中央顾问委员会委员致党的十二届四中全会的信"},"next":{"text":"中国共产党十二届四中全会给叶剑英同志的致敬信","link":"./中国共产党十二届四中全会给叶剑英同志的致敬信"}},"headers":[],"relativePath":"12/4/三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信.md","filePath":"12/4/三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信.md"}'),s={name:"12/4/三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信.md"};function i(p,_,n,c,o,l){return e(),a("div",null,[..._[0]||(_[0]=[r('<h1 id="三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信" tabindex="-1">三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信 <a class="header-anchor" href="#三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信" aria-label="Permalink to &quot;三十位老同志请求不再担任中国共产党中央纪律检查委员会委员致党的十二届四中全会的信&quot;">​</a></h1><div class="text-center-lg"><p class="sig-text">中国共产党第十二届中央委员会<br>第四次全体会议：</p></div><p>  即将召开的党的全国代表会议，准备根据干部队伍革命化、年轻化、知识化、专业化的要求，增选一批中央委员会委员和候补委员、中央顾问委员会委员、中央纪律检查委员会委员，这是党和国家政治生活中的一件大事。我们衷心拥护中央这一重大决策。</p><p>  我们这些同志在本届中央纪律检查委员会已经工作了三年，在党中央的领导下，为维护党纪，端正党风，做了一些事情，尽了一份力量。现在，我们年事已高，有的体弱多病，无力继续担任繁重的工作，恳切请求不再担任中央纪律检查委员会委员，以便增选一批比较年轻的优秀干部进入中央纪律检查委员会。</p><p>  在为实现党风根本好转和社会风气根本好转的艰巨的工作和斗争中，中央和全党交付给中央纪律检查委员会以重任。我们相信，经过调整部分成员以后，中央纪律检查委员会的力量将进一步加强，党的纪律检查工作也将进一步加强，更好地保证我国各项改革的顺利进行和社会主义现代化建设事业的蓬勃发展。</p><p>  我们从中纪委委员的岗位上退下来以后，将继续关心党的纪律检查工作，继续为党、为人民、为共产主义的伟大事业，贡献自己的力量。</p><p>  致共产主义的敬礼！</p><div class="sig-block-a"><div class="sig-content"><p class="sig-text"> 黄克诚 王从吾 李 昌 马国瑞 蔡顺礼<br> 王 凌 王尧山 王鹤峰 毛 铎 朱绍清<br> 刘 英 刘汉生 严克伦 李 耀 吴信泉<br> 张海峰 陈 坦 林一心 金昭典 段 云<br> 饶正锡 徐深吉 郭 建 唐延杰 黄民伟<br> 曹广化 曹幼民 彭 儒 谭申平 蹇先任<br> 一九八五年八月 </p></div></div>',8)])])}const m=t(s,[["render",i]]);export{b as __pageData,m as default};
